import 'package:flutter/material.dart';
import '../../../services/workflow_service.dart';
import '../../../l10n/app_localizations.dart';
import '../../../widgets/premium_states.dart';
import '../../../widgets/premium_ui.dart';

class AdminAnalyticsG2Screen extends StatefulWidget { const AdminAnalyticsG2Screen({super.key}); @override State<AdminAnalyticsG2Screen> createState() => _AdminAnalyticsG2ScreenState(); }
class _AdminAnalyticsG2ScreenState extends State<AdminAnalyticsG2Screen> {
  bool _loading=true; String? _error; Map<String,dynamic>? _data; int _days=30; String? _group;
  Future<void> _load() async { setState((){_loading=true;_error=null;}); try { final now=DateTime.now(); final result=await WorkflowService.call('adminAnalytics',{'startMs':now.subtract(Duration(days:_days)).millisecondsSinceEpoch,'endMs':now.millisecondsSinceEpoch,'forceRefresh':true,if(_group!=null)'bloodGroup':_group}); if(mounted)setState(()=>_data=Map<String,dynamic>.from(result)); } catch(e){if(mounted)setState(()=>_error=e.toString());} finally{if(mounted)setState(()=>_loading=false);} }
  @override void initState(){super.initState();_load();}
  @override Widget build(BuildContext context){ final l=AppLocalizations.of(context); if(_loading)return const PremiumLoading(); if(_error!=null)return PremiumErrorState(onRetry:_load,message:l.somethingWentWrong); final d=_data; if(d==null)return PremiumEmptyState(title:l.somethingWentWrong,onAction:_load,actionLabel:l.retry); final counts=Map<String,dynamic>.from(d['counts']??{}), donors=Map<String,dynamic>.from(d['donors']??{}), rr=Map<String,dynamic>.from(d['responseRate']??{}), fr=Map<String,dynamic>.from(d['fulfilmentRate']??{}); return SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(l.analyticsTitle,style:Theme.of(context).textTheme.headlineSmall)),DropdownButton<int>(value:_days,items:[7,30,90].map((x)=>DropdownMenuItem(value:x,child:Text('$x days'))).toList(),onChanged:(x){if(x!=null){setState(()=>_days=x);_load();}}),IconButton(onPressed:_load,icon:const Icon(Icons.refresh),tooltip:l.refresh)]),Wrap(spacing:8,children:[DropdownButton<String?>(value:_group,hint:Text(l.bloodGroupFilter),items:[null,'A+','A-','B+','B-','AB+','AB-','O+','O-'].map((x)=>DropdownMenuItem<String?>(value:x,child:Text(x??'All'))).toList(),onChanged:(x){setState(()=>_group=x);_load();}),if(d['approximate']==true)Text(l.analyticsApproximate)]),const SizedBox(height:16),Wrap(spacing:12,runSpacing:12,children:[_card(l.totalDonors,donors['total']),_card(l.activeDonors,donors['active']),_card(l.verifiedDonors,donors['verified']),_card(l.openRequests,counts['open']),_card(l.fulfilledRequests,counts['fulfilled']),_card(l.pendingVerifications,d['pendingVerifications']),_card('Response', '${rr['numerator']??0} of ${rr['denominator']??0}'),_card('Fulfilment', '${fr['numerator']??0} of ${fr['denominator']??0}')]),PremiumSectionHeader(title:l.requestStatusSummary),...counts.entries.map((e)=>ListTile(title:Text(e.key),trailing:Text('${e.value}'))),Text('${l.lastUpdated}: ${DateTime.fromMillisecondsSinceEpoch((d['generatedAt'] as num).toInt()).toLocal()}') ])); }
  Widget _card(String title,dynamic value)=>SizedBox(width:180,child:PremiumCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title),const SizedBox(height:8),Text('${value??0}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold))])));
}
